powershell.exe -Command ########################################################################
# COPYRIGHT (C) 2012-2018, Rapid7 LLC, Boston, MA, USA.
# All rights reserved.
########################################################################

$tempDir = \"$($env:TEMP)\rapid7\"
$logFileFullPath = \"$tempDir\powershell.log\"

function Main {
    $collectorUrl = \"https://R7BETALAB-SW02.R7BETALAB.local:20000\"
    $agentExecutable = \"ir_agent.exe\"
    $agentVersion = 1712348425
    $agentUUID = \"1e448100d04ef609c75a29aff79a3d4e\"
    $unzipUtilFullPath = \"$tempDir\7za.exe\"

    Create-TempDir-If-Not-Present $tempDir
    Recreate-Log-File $logFileFullPath

    if (IsAgentRunning $agentExecutable) {
        Write-Log $logFileFullPath \"Rapid7 Persistent agent is already running. Skipping scan...\"
        Exit
    }

    Stop-Process -Name \"honeyhashx86\" -Force | Out-Null

    $agentAlreadyDownloaded = IsDownloadedAgentLatest $tempDir $collectorUrl $agentVersion $logFileFullPath           
    if (-Not $agentAlreadyDownloaded) {

        Write-Log $logFileFullPath \"Downloading agent zip version: $agentVersion\"

        # Delete everything for a fresh start
        Create-TempDir $tempDir

        Try {
            Download-Agent $tempDir $collectorUrl $agentVersion $logFileFullPath $unzipUtilFullPath
            Expand-Agent $tempDir\agent-$agentVersion.zip $tempDir $unzipUtilFullPath $logFileFullPath
        } Catch {
            Write-Exception $logFileFullPath $_ \"Error while downloading Agent. CollectorURL: $collectorUrl\"
            Exit
        }
    }

    # if Launch-Agent returns true, then we should re-download and launch the agent
    # otherwise, just terminate
    Write-Log $logFileFullPath \"Launching dissolvable agent...\"
    Launch-Agent $agentUUID $tempDir $agentExecutable $logFileFullPath
}

function Create-TempDir-If-Not-Present($tempDir) {
    if (-Not (Test-Path $tempDir)) {
        New-Item -Path $tempDir -ItemType Directory | Out-Null
    }

    Set-Location $tempDir
}

function Recreate-Log-File($logFileFullPath) {

    #Check if file exists and delete if it does
    If((Test-Path -Path $logFileFullPath)){
      Remove-Item -Path $logFileFullPath -Force
    }

    New-Item -Path $logFileFullPath -ItemType File | Out-Null
    Write-Log $logFileFullPath \"Starting powershell to launch Rapid7 Agent\"
}

function Write-Log($logFileFullPath, $message) {
    $dateTime = Get-Date
    Add-Content $logFileFullPath \"$dateTime $message`n\"
}

function Write-Exception($logFileFullPath, $psItem, $message=\"\") {
    $ex = $psItem.Exception
    $stackTrace = $psItem.Exception
    $errorMsg = \"\"
    while ($ex -ne $null -and $ex.Message -ne $null) {
        if ($errorMsg -ne \"\") {
            $errorMsg = \"${errorMsg}. Caused By: \"
        }
        $exMsg = $ex.Message
        $errorMsg = \"${errorMsg}${exMsg}\"
        $ex = $ex.InnerException
    }
    if ($errorMsg -ne \"\") {
        if ($message -ne \"\") {
            $message = \"${message}. \"
        }
        $errorMsg = \"Exception: ${errorMsg}\"
    }
    Write-Log $logFileFullPath \"${message}${errorMsg}${stackTrace}\"
}

function IsAgentRunning($executable) {
    $processName = [io.path]::GetFileNameWithoutExtension($executable)
    # Check if any current agents are running in the tempDir and kill if found
    $processPids = Get-Process $processName | Select -Expand id
    if ($processPids -ne $null) {
        foreach($processPid in $processPids) {
            $processPath = (Get-Process -id $processPid).Path
            if ($processPath -like \"*\Temp\*\") {
                Write-Log $logFileFullPath \"Killing dissolvable agent running at: $processPath\"
                Stop-Process -id $processPid -Force
            }
        }
    } else {
        return $false
    }

    # After killing all agents running from tempDir check again for persistent agent
    $processes = Get-Process | Where-Object { $_.Name -eq $processName }
    return ($processes -ne $null)
}

function IsDownloadedAgentLatest($tempDir, $collectorUrl, $agentVersion, $logFileFullPath) {
    $agentPath = \"$tempDir\agent-$agentVersion.zip\"
    $pythonLibraryPath = \"$tempDir\library.zip\"

    $agentPathExists = Test-Path $agentPath
    $pythonLibraryPathExists = Test-Path $pythonLibraryPath

    if ($agentPathExists -and $pythonLibraryPathExists) {
        # Even when agent is at current version, still download new config and certificates
        Try {
            $agentPath = Download-Agent $tempDir $collectorUrl $agentVersion $logFileFullPath $unzipUtilFullPath $false
            Expand-Agent $tempDir\config.zip $tempDir $unzipUtilFullPath $logFileFullPath
        } Catch {
            Write-Exception $logFileFullPath $_ \"Failed to download new configuration. CollectorURL: $collectorUrl\"
            Exit
        }
    }

    return $agentPathExists -and $pythonLibraryPathExists
}

function Create-TempDir($tempDir) {
    if (Test-Path $tempDir) {
        Remove-Item $tempDir\* -Recurse -exclude *.log,config
    }

    New-Item -Path $tempDir -ItemType Directory | Out-Null
    Set-Location $tempDir
}

function Download-Agent($tempDir, $collectorUrl, $agentVersion, $logFileFullPath, $unzipUtilPath, $entireAgent = $true) {
    [System.Net.ServicePointManager]::ServerCertificateValidationCallback = {
        param ($sender, $certificate, $chain, $SslPolicyErrors)
        $certificate.GetCertHashString().ToUpper() -eq \"7977e77bf315b223af5efddd0d4078743e5cfd0a\"
    }

    try {
        $webClient = New-Object System.Net.WebClient

        #download unzip utility
        if (-Not (Test-Path $unzipUtilPath)) {
            Write-Log $logFileFullPath \"Downloading 7-zip utility\"

            $webClient.DownloadFile(\"$collectorUrl/7zip\", $unzipUtilPath)
        }

        if ($entireAgent -eq $true) {
            $procInfo = Get-WmiObject -Class Win32_Processor

            if ($procInfo.AddressWidth -eq 64) {
                $platform = \"WINDOWS_X86_64\"
            } else { 
                $platform = \"WINDOWS_X86\"
            }

            Write-Log $logFileFullPath \"Downloading $platform agent zip\"            
            $webClient.DownloadFile(\"$collectorUrl/agent?platform=$platform\",
                \"$($tempDir)\agent-$($agentVersion).zip\")
        } else {
            Write-Log $logFileFullPath \"Downloading configuration and certificate zip\"
            $webClient.DownloadFile(\"$collectorUrl/config\", \"$($tempDir)\config.zip\")
        }
    } finally {
        $webClient.Dispose()
    }
}

function Expand-Agent($pathToExpand, $tempDir, $unzipUtilFullPath, $logFileFullPath) {
    Get-ChildItem $pathToExpand | % {& $unzipUtilFullPath \"x\" \"-aoa\" \"-y\" $_.fullname \"-o$tempDir\"}

    Write-Log $logFileFullPath \"$pathToExpand successfully extracted.\"
}

function Launch-Agent($agentUUID, $agentPath, $agentExecutable, $logFileFullPath) {
    & \"$tempDir\$agentExecutable\" -i $agentUUID -a $tempDir -b $tempDir

    Write-Log $logFileFullPath \"Agent Launched with Exit code: $LastExitCode\"
}

Try {
    Main
} Catch {
    Write-Exception $logFileFullPath $_
    Exit
}

